def empresa_padrao():
    """
    Empresa usada nas mensagens recebidas pelo webhook. Consulta na hora do
    uso (e não ao importar o módulo), para o sistema conseguir iniciar mesmo
    antes de o banco estar migrado.
    """
    return Empresa.objects.first()

@csrf_exempt
@require_http_methods(["GET", "POST"])
def whatsapp_webhook(request):
    """Webhook único — trata verificação (GET) e mensagens (POST)"""
    if request.method == "GET":
        verify_token = request.GET.get("hub.verify_token")
        challenge = request.GET.get("hub.challenge")
        if verify_token == VERIFY_TOKEN:
            return HttpResponse(challenge)
        return JsonResponse({"error": "Token inválido"}, status=403)

    elif request.method == "POST":
        try:
            print("Recebido webhook do WhatsApp")
            print(request.body)                        
            data = json.loads(request.body.decode("utf-8"))
            print(data)
            if data:
                msg = data
                sender = msg.get("from")
                print(f"Mensagem recebida de {sender}")
                if msg.get("type") == "interactive":
                    button_reply = msg["interactive"]["button_reply"]["id"]
                    HistoricoMensagem.objects.create(
                        phone_number=sender,
                        mensagem=f"Botão clicado: {button_reply}",
                        direcao="recebida",
                        tipo="botao",
                        empresa=empresa_padrao(),
                    )
                    resposta = handle_button_click(sender, button_reply)                                    
                else:
                    print("Processando mensagem de texto")
                    print(msg)
                    text = msg.get("message")
                    
                    print(f"Conteúdo da mensagem: {text}")
                    """"HistoricoMensagem.objects.create(
                        phone_number=sender,
                        mensagem=text,
                        direcao="recebida",
                        tipo="texto",
                        empresa=empresa_padrao(),
                    )"""
                    resposta = process_message(sender, text)

            return JsonResponse(resposta)
        except Exception as e:
            print(f"Erro ao processar webhook: {str(e)}")
            return JsonResponse({"error": str(e)}, status=400)


# ========================== PROCESSAMENTO DE MENSAGENS ==========================

def process_message(phone_number, message_body):
    """Processa mensagens de texto normais e controla o fluxo multi-step"""
    print(f"Processando mensagem de {phone_number}: {message_body}")
    message_body = message_body.strip()

    # Inicializa agenda do usuário
    agenda = USER_AGENDA.setdefault(phone_number, {"active": False, "step": 0})

    # Comandos exclusivos do ALERT_NUMBER (criação automática)
    if phone_number == ALERT_NUMBER:
        if message_body.lower().startswith("criar orcamento "):
            parts = message_body.replace("criar orcamento ", "").split(";")
            if len(parts) >= 6:
                client_number = parts[0].strip()
                nome = parts[1].strip()
                endereco = parts[2].strip()
                data_evento = parts[3].strip()
                horario = parts[4].strip()
                itens = [i.strip() for i in parts[5].split(",")]
                criar_orcamento_alert(client_number, nome, endereco, data_evento, horario, itens)
                return
            else:
                return send_text_message(ALERT_NUMBER,
                                  "❌ Formato inválido. Use: CRIAR ORCAMENTO [número];[nome];[endereço];[data];[horário];[itens]")
        elif message_body.lower() == "ajuda orcamento":
            return send_text_message(ALERT_NUMBER,
                              "📋 Para criar orçamento: CRIAR ORCAMENTO [número];[nome];[endereço];[data];[horário];[itens]")

    # Fluxo multi-step para orçamento via WhatsApp
    if agenda.get("active"):
        print("Usuário em fluxo ativo")
        step = agenda.get("step", 1)
        try:
            if step == 0:
                #verifica se a mensagem é um número de 1 a 4
                if message_body in ["1", "2", "3", "4"]:
                    return handle_button_click(phone_number, message_body)
                else:
                    #verifica se a mensagem é uma das opções do menu inicial
                    possiveis_opcoes = {
                        "catálogo de brinquedos": "1",
                        "pré-orçamento": "2",
                        "dúvidas sobre agendamento": "3",
                        "falar com atendente": "4",
                    }
                    opcao = possiveis_opcoes.get(message_body.lower())
                    if opcao:
                        return handle_button_click(phone_number, opcao)
                    else:
                        return send_text_message(phone_number, "❌ Opção inválida. Por favor, responda com *1*, *2*, *3* ou *4* para continuar.")
            if step == 1:
                USER_AGENDA[phone_number]["nome"] = message_body
                USER_AGENDA[phone_number]["step"] = 2
                return send_text_message(phone_number, "📍 Pode me informar o endereço do evento, por favor?")
                
            elif step == 2:
                USER_AGENDA[phone_number]["endereco"] = message_body
                USER_AGENDA[phone_number]["step"] = 3
                return send_text_message(phone_number, "📅 Que dia vai acontecer o evento? (Formato: dd/mm/aaaa)")
                
            elif step == 3:
                # validação da data
                if len(message_body) != 10 or message_body[2] != "/" or message_body[5] != "/":
                    return send_text_message(phone_number, "❌ Ops! Formato inválido. Use o formato: dd/mm/aaaa 😊")
                    
                if int(message_body[0:2]) < 1 or int(message_body[0:2]) > 31:
                    return send_text_message(phone_number, "❌ Dia inválido. Tente novamente usando o formato: dd/mm/aaaa")
                  
                if int(message_body[3:5]) < 1 or int(message_body[3:5]) > 12:
                    return send_text_message(phone_number, "❌ Mês inválido. Tente novamente usando o formato: dd/mm/aaaa")
                  

                data_obj = datetime.strptime(message_body, "%d/%m/%Y")
                data = data_obj.strftime("%Y-%m-%d")
                USER_AGENDA[phone_number]["data"] = data
                USER_AGENDA[phone_number]["step"] = 4
                return send_text_message(phone_number, "⏰ Que horas está previsto o início do evento? (Ex: 14:00)")
                
            elif step == 4:
                USER_AGENDA[phone_number]["hora_evento"] = normalizar_hora(message_body)
                print(f"Horário normalizado: {USER_AGENDA[phone_number]['hora_evento']}")
                itens = Item.objects.filter(disponivel=True, empresa_id=1)
                if not itens:
                    USER_AGENDA[phone_number]["active"] = False
                    return send_text_message(phone_number, "😔 No momento não temos brinquedos disponíveis para locação.")
                    
                lista = "🎪 Olha só os brinquedos disponíveis pra seu evento:\n\n"
                for i in itens:
                    lista += f"{i.id}. {i.nome} - R$ {i.valor_unitario:.2f}\n"
                lista += "\n👉 Envie os números dos brinquedos desejados, separados por vírgula."
                USER_AGENDA[phone_number]["step"] = 5
                return send_text_message(phone_number, lista)

            elif step == 5:
                selecionados = [s.strip() for s in message_body.split(",") if s.strip().isdigit()]
                USER_SELECTIONS[phone_number] = {"itens": selecionados}
                USER_AGENDA[phone_number]["step"] = 6
                return send_text_message(phone_number, "📍 Seu evento será realizado em Cajazeiras? (Responda com *sim* ou *não*) 🤗")
            elif step == 6:
                resposta = interpretar_sim_nao(message_body)

                if resposta is None:
                    return send_text_message(phone_number, "❌ Não entendi. Por favor, responda com *sim* ou *não* 😉")

                if resposta:  # Se for sim
                    USER_AGENDA[phone_number]["valor_adicional"] = 0
                    """else:  # Se for não
                        return send_text_message(phone_number, "🚚 Certo! Nesse caso, pode me informar a cidade ou local do evento? Assim calculamos o deslocamento 😊")
                        USER_AGENDA[phone_number]["step"] = "local_evento"
                        return
                    """
                else:
                    USER_AGENDA[phone_number]["valor_adicional"] = 30
                    
                USER_AGENDA[phone_number]["step"] = 7
                return send_text_message(phone_number, "💳 O pagamento será à vista? (Responda com *sim* ou *não*)")
                

            elif step == 7:
                try:
                    resposta = interpretar_sim_nao(message_body)
                    desconto = 0
                    if resposta is None:
                        return send_text_message(phone_number, "❌ Não entendi. Por favor, responda com *sim* ou *não* 😉")

                    if resposta:  # Se for sim
                        desconto = Decimal("5")
                    else:
                        desconto = Decimal("0")
                except:
                    print("Erro ao interpretar resposta de pagamento.")
                    desconto = Decimal("0")
                    
                USER_AGENDA[phone_number]["desconto"] = desconto

                orcamento = cria_orcamento_do_cliente(phone_number,
                                                    USER_AGENDA[phone_number],
                                                    USER_SELECTIONS[phone_number])
                pdf, _ = gerar_arquivos(orcamento)
                enviar_documento_whatsapp(
                    phone_number,
                    pdf,
                    caption=f"📋 Orçamento Mundo Kids - {USER_AGENDA[phone_number].get('nome')}",
                    filename=f"orcamento_{phone_number}.pdf"
                )
                
        except Exception as e:
            print(f"Erro no processamento do step {step} para {phone_number}: {str(e)}")
            return send_text_message(phone_number, "❌ Ocorreu um erro. Por favor, tente novamente.")
    else:
        # Usuário novo ou menu inicial
        print("Enviando menu inicial")
        return send_welcome_initial(phone_number)




# ========================== FLUXO DE BOTÕES ==========================

def send_quick_attendance_button(to_number, number_of_buttons="ALL"):
    """Envia menu interativo de atendimento rápido com botões de reply"""
    url = f"https://graph.facebook.com/v20.0/{PHONE_NUMBER_ID}/messages"
    headers = {
        "Authorization": f"Bearer {WHATSAPP_TOKEN}",
        "Content-Type": "application/json",
    }

    # Monta a lista de botões conforme parâmetro
    buttons = []
    if number_of_buttons == "ALL":
        buttons = [
            {"type": "reply", "reply": {"id": "duvidas_locacao", "title": "Dúvidas locação"}},
            {"type": "reply", "reply": {"id": "realizar_orcamento", "title": "Realizar orçamento"}},
            {"type": "reply", "reply": {"id": "ver_catalogo", "title": "Ver catálogo"}},
        ]
    elif number_of_buttons == "ONE":
        buttons = [
            {"type": "reply", "reply": {"id": "duvidas_locacao", "title": "Dúvidas locação"}}
        ]
    elif number_of_buttons == "TWO":
        buttons = [
            {"type": "reply", "reply": {"id": "duvidas_locacao", "title": "Dúvidas locação"}},
            {"type": "reply", "reply": {"id": "realizar_orcamento", "title": "Realizar orçamento"}}
        ]
    elif number_of_buttons == "THREE":
        buttons = [
            {"type": "reply", "reply": {"id": "duvidas_locacao", "title": "Dúvidas locação"}},
            {"type": "reply", "reply": {"id": "realizar_orcamento", "title": "Realizar orçamento"}},
            {"type": "reply", "reply": {"id": "ver_catalogo", "title": "Ver catálogo"}},
        ]

    payload = {
        "messaging_product": "whatsapp",
        "to": to_number,
        "type": "interactive",
        "interactive": {
            "type": "button",
            "body": {"text": "Escolha uma opção 👇"},
            "action": {"buttons": buttons}
        }
    }

    response = requests.post(url, headers=headers, json=payload)
    if response.status_code != 200:
        print(f"Erro ao enviar botões: {response.status_code} - {response.text}")


def handle_button_click(phone_number, button_id):
    """Processa cliques de botões"""
    if button_id == "3":
        return send_text_message(phone_number,
                          "Nossas locações incluem brinquedos, mesas, cadeiras e muito mais. Deseja receber o catálogo completo?")
        send_quick_attendance_button(phone_number, number_of_buttons="THREE")
    elif button_id == "2":
        #pelo número do telefone verifica se já existe um cliente
        clienteName = Cliente.objects.filter(telefone=phone_number).first()
        if clienteName:
            agenda = USER_AGENDA.setdefault(phone_number, {"active": True, "step": 2})
            agenda["nome"] = clienteName.nome
            agenda["active"] = True
            agenda["step"] = 2  
            mensagem = (
                f"📝 Olá {clienteName.nome}, vamos iniciar um novo pré-orçamento!/n/n"
                "📍 Pode me informar o endereço do evento, por favor?"
            )
            return send_text_message(phone_number, mensagem)
        else:
            # Inicializa usuário e step        
            agenda = USER_AGENDA.setdefault(phone_number, {"active": True, "step": 1})
            agenda["active"] = True
            agenda["step"] = 1  # Step 1 = nome do cliente
            return send_text_message(phone_number, "📝 Vamos começar o seu pré-orçamento! Qual é o seu nome?")
    elif button_id == "1":
        return send_text_message(phone_number, "Confira nosso catálogo aqui: https://seudominio.com/catalogo")
    elif button_id == "confirmar_agendamento":
        return send_text_message(phone_number, "Ótimo! Um de nossos atendentes entrará em contato em breve para finalizar o agendamento.", CHAT_SUPPORT=True)

    elif button_id == "cancelar_agendamento":
        USER_AGENDA[phone_number]["active"] = False
        return send_text_message(phone_number, "Sem problemas! Se precisar de algo mais, é só chamar. Estamos aqui para ajudar!")

    elif button_id == "4":
        return send_text_message(phone_number, "Um de nossos atendentes entrará em contato com você em breve. Obrigado pelo contato!", CHAT_SUPPORT=True)
    else:
        return send_text_message(phone_number, "Opção inválida. Digite *menu* para ver as opções novamente.")


# ========================== FUNÇÕES DE ORÇAMENTO ==========================

def criar_orcamento_alert(client_number, nome, endereco, data_evento, horario, itens):
    """Cria orçamento e envia para ALERT_NUMBER"""
    data_obj = datetime.strptime(data_evento, "%d/%m/%Y")
    data = data_obj.strftime("%Y-%m-%d")
    USER_AGENDA[client_number] = {
        "nome": nome,
        "telefone": client_number,
        "endereco": endereco,
        "data": data, 
        "hora_evento": horario,
        "active": True
    }

    combos, brinquedos = [], []
    for item in itens:
        if item.startswith("combo"):
            combos.append(item)
        elif item in BRINQUEDOS:
            brinquedos.append(item)

    USER_SELECTIONS[client_number] = {"combos": combos, "brinquedos": brinquedos}

    # Gera PDF temporário
    with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp_file:
        pdf_path = tmp_file.name

    gerar_pdf_orcamento(pdf_path, USER_AGENDA[client_number], USER_SELECTIONS[client_number])

    # Envia PDF para ALERT_NUMBER
    enviar_documento_whatsapp(ALERT_NUMBER, pdf_path,
                              caption=f"📋 Orçamento criado para {nome} - {client_number}",
                              filename=f"orcamento_{client_number}.pdf")

    return send_text_message(ALERT_NUMBER, f"✅ Orçamento criado para {nome} - {client_number}")


def gerar_pdf_orcamento(file_path, dados_cliente, itens_selecionados):
    """Gera PDF simples do orçamento"""
    c = canvas.Canvas(file_path, pagesize=A4)
    width, height = A4
    c.setFont("Helvetica-Bold", 16)
    c.drawString(50, height - 50, "Mundo Kids - Orçamento")
    c.setFont("Helvetica", 12)
    c.drawString(50, height - 80, f"Cliente: {dados_cliente.get('nome', 'N/A')}")
    c.drawString(50, height - 100, f"Telefone: {dados_cliente.get('telefone', 'N/A')}")
    c.drawString(50, height - 120, f"Endereço: {dados_cliente.get('endereco', 'N/A')}")
    c.drawString(50, height - 140, f"Data: {dados_cliente.get('data', 'N/A')}")
    c.drawString(50, height - 160, f"Horário: {dados_cliente.get('hora_evento', 'N/A')}")

    y = height - 200
    total = 0
    for combo_id in itens_selecionados.get("combos", []):
        combo = COMBOS[combo_id]
        c.setFont("Helvetica-Bold", 12)
        c.drawString(50, y, f"Combo: {combo['nome']} - R$ {combo['preco']:.2f}")
        y -= 20
        total += combo['preco']

    for brinquedo_id in itens_selecionados.get("brinquedos", []):
        brinquedo = BRINQUEDOS[brinquedo_id]
        c.setFont("Helvetica", 12)
        c.drawString(50, y, f"{brinquedo['nome']} - R$ {brinquedo['preco']:.2f}")
        y -= 20
        total += brinquedo['preco']

    c.setFont("Helvetica-Bold", 14)
    c.drawString(50, y - 30, f"Total: R$ {total:.2f}")
    c.save()


