from .models import HistoricoMensagem

def send_text_message(to_number, text, salva=True, direcao="enviada", tipo="texto", CHAT_SUPPORT=False):
    print(f"Enviando mensagem de texto: {text}")
    return {
        "support_chat": CHAT_SUPPORT,
        "acao": "send_text",
        "mensagem": text
    }



def enviar_documento_whatsapp(to_number, file_path, caption="", filename="documento.pdf"):
    """
    NÃO envia o documento diretamente.
    Apenas informa ao n8n que um documento deve ser enviado.
    """

    return {
        "acao": "send_document",
        "to": to_number,
        "arquivo": file_path,
        "filename": filename,
        "caption": caption
    }



