def gerar_pdf_orcamento_whatsapp(phone_number):
    dados = USER_AGENDA[phone_number]
    itens_ids = USER_SELECTIONS[phone_number].get("itens", [])

    # Consulta os itens no banco
    itens_objs = Item.objects.filter(id__in=itens_ids)

    total = 0
    with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp_file:
        pdf_path = tmp_file.name

    from reportlab.pdfgen import canvas
    from reportlab.lib.pagesizes import A4

    c = canvas.Canvas(pdf_path, pagesize=A4)
    width, height = A4
    c.setFont("Helvetica-Bold", 16)
    c.drawString(50, height - 50, "Mundo Kids - Orçamento WhatsApp")
    c.setFont("Helvetica", 12)
    c.drawString(50, height - 80, f"Cliente: {dados.get('nome')}")
    c.drawString(50, height - 100, f"Endereço: {dados.get('endereco')}")
    c.drawString(50, height - 120, f"Data: {dados.get('data')}")
    c.drawString(50, height - 140, f"Horário: {dados.get('hora_evento')}")

    y = height - 180
    for item in itens_objs:
        c.drawString(50, y, f"{item.nome} - R$ {item.preco:.2f}")
        y -= 20
        total += item.preco

    total += dados.get("valor_adicional", 0)
    total -= total * (dados.get("desconto", 0) / 100)

    c.setFont("Helvetica-Bold", 14)
    c.drawString(50, y - 20, f"Total: R$ {total:.2f}")
    c.save()

    enviar_documento_whatsapp(phone_number, pdf_path,
                              caption=f"📋 Orçamento Mundo Kids - {dados.get('nome')}",
                              filename=f"orcamento_{phone_number}.pdf")


from datetime import datetime

from decimal import Decimal
from datetime import datetime

def safe_decimal(value):
    if value is None or value == "":
        return Decimal("0.0")
    try:
        return Decimal(str(value))
    except (TypeError, ValueError, InvalidOperation):
        return Decimal("0.0")

def cria_orcamento_do_cliente(phone_number, dados_cliente, itens_selecionados):
    empresaMundoKids = Empresa.objects.get(id=1)
    
    cliente, criado = Cliente.objects.get_or_create(
        telefone=phone_number,
        empresa=empresaMundoKids,
        defaults={"nome": dados_cliente.get("nome", "Cliente WhatsApp")}
    )

    data_evento_str = dados_cliente.get("data")
    data_evento = None
    if data_evento_str:
        for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
            try:
                data_evento = datetime.strptime(data_evento_str, fmt).date()
                break
            except ValueError:
                continue

    valor_adicional = safe_decimal(dados_cliente.get("valor_adicional"))
    desconto = safe_decimal(dados_cliente.get("desconto"))

    orcamento = Orcamento.objects.create(
        empresa=empresaMundoKids,
        cliente=cliente,
        endereco=dados_cliente.get("endereco", ""),
        data_evento=data_evento,
        valor_adicional=valor_adicional,
        desconto_geral=desconto,
        hora_evento=dados_cliente.get("hora_evento", None),
    )

    for item_id in itens_selecionados.get("itens", []):
        try:
            item = Item.objects.get(id=item_id)
            orcamento.itens.create(item=item, quantidade=1, valor=item.valor_unitario, desconto=0)
        except Item.DoesNotExist:
            continue

