def normalizar_hora(texto: str) -> str | None:
    if not texto:
        print("Texto vazio para normalização de hora.")
        return None

    # Limpa e normaliza
    hora = texto.strip().lower()
    if(len(hora) > 5):
        print("Texto muito longo para hora. " + texto)
        return None
    if len(hora) == 3:
        hora = hora.replace("h", ":00")
    else:        
        hora = hora.replace("h", ":").replace(" ", "")
    hora = hora.replace(".", ":")
    print(f"Hora após limpeza: {hora}")
    # Formatos aceitos
    if re.match(r"^\d{1,2}$", hora):
        # Ex: "18" -> "18:00"
        hora = f"{int(hora):02d}:00"
    elif re.match(r"^\d{1,2}:\d{1,2}$", hora):
        # Ex: "18:3" -> "18:03"
        h, m = hora.split(":")
        hora = f"{int(h):02d}:{int(m):02d}"
    else:
        print("Formato de hora inválido. " + texto)
        return None  # formato inválido

    # Validação de faixa
    try:
        h, m = map(int, hora.split(":"))
        if not (0 <= h <= 23 and 0 <= m <= 59):
            print("Hora fora da faixa válida. " + texto)
            return None
    except ValueError:
        print("Erro ao converter hora e minuto para inteiros. " + texto)
        return None

    return hora

