def interpretar_sim_nao(texto: str) -> bool | None:
    """
    Interpreta respostas de sim/não em texto livre.
    Retorna True se for sim, False se for não, e None se não conseguir identificar.
    """
    if not texto:
        return None

    texto = texto.strip().lower()

    # Possíveis variações de "sim"
    respostas_sim = {"sim", "s", "ss", "claro", "positivo", "ok", "isso", "affirmativo", "afirmativo", "pode", "uhum", "aham"}
    # Possíveis variações de "não"
    respostas_nao = {"nao", "não", "n", "nn", "negativo", "nunca", "jamais", "nope"}

    if texto in respostas_sim:
        return True
    elif texto in respostas_nao:
        return False
    else:
        return None

