from django.db.models import Max, Count, Q, OuterRef, Subquery
from django.core.paginator import Paginator
from django.utils import timezone
from datetime import timedelta

def historico_mensagens(request):
    """Lista todos os números com mensagens com informações enriquecidas"""
    # Subquery para pegar a última mensagem de cada conversa
    ultima_mensagem_subquery = HistoricoMensagem.objects.filter(
        phone_number=OuterRef('phone_number')
    ).order_by('-data_envio').values('mensagem')[:1]
    
    # Subquery para pegar o tipo da última mensagem
    ultimo_tipo_subquery = HistoricoMensagem.objects.filter(
        phone_number=OuterRef('phone_number')
    ).order_by('-data_envio').values('tipo')[:1]
    
    conversas = HistoricoMensagem.objects.filter(
    nome_cliente__isnull=False
    ).exclude(
        nome_cliente=''
    ).values("phone_number", "nome_cliente").annotate(
        last_message_time=Max('data_envio'),
        total_messages=Count('id'),
        unread_count=Count('id', filter=Q(direcao='recebida')),
        last_message=Subquery(ultima_mensagem_subquery),
        last_message_type=Subquery(ultimo_tipo_subquery)
    ).distinct().order_by("-last_message_time")
    
    # Filtros via GET
    search_query = request.GET.get('search', '')
    tipo_filter = request.GET.get('tipo', '')
    sort_by = request.GET.get('sort', 'recent')
    
    if search_query:
        conversas = conversas.filter(
            Q(nome_cliente__icontains=search_query) | 
            Q(phone_number__icontains=search_query)
        )
    
    if tipo_filter and tipo_filter != 'all':
        conversas = conversas.filter(last_message_type=tipo_filter)
    
    # Ordenação
    if sort_by == 'name':
        conversas = conversas.order_by('nome_cliente')
    elif sort_by == 'oldest':
        conversas = conversas.order_by('last_message_time')
    else:  # recent (padrão)
        conversas = conversas.order_by('-last_message_time')
    
    # Paginação
    paginator = Paginator(conversas, 20)
    page_number = request.GET.get('page')
    page_obj = paginator.get_page(page_number)
    
    # Estatísticas para os filtros
    total_conversas = conversas.count()
    conversas_recentes = conversas.filter(
        last_message_time__gte=timezone.now() - timedelta(days=1)
    ).count()
    
    return render(request, "whatsapp/historico_mensagens.html", {
        "conversas": page_obj,
        "page_obj": page_obj,
        "total_conversas": total_conversas,
        "conversas_recentes": conversas_recentes,
        "TIPO_CHOICES": HistoricoMensagem.TIPO_CHOICES
    })

from django.http import JsonResponse
import json

def chat_cliente(request, phone_number):
    """Exibe o chat completo com o cliente"""
    
    # Verificar se é uma requisição AJAX para verificar novas mensagens
    if request.headers.get('X-Requested-With') == 'XMLHttpRequest' and request.method == 'GET':
        last_message_id = request.GET.get('last_message_id', 0)
        
        try:
            last_message_id = int(last_message_id)
        except (ValueError, TypeError):
            last_message_id = 0
            
        # Buscar novas mensagens
        novas_mensagens = HistoricoMensagem.objects.filter(
            phone_number=phone_number,
            id__gt=last_message_id
        ).select_related('usuario').order_by('data_envio')
        
        # Serializar as mensagens
        mensagens_data = []
        for msg in novas_mensagens:
            mensagens_data.append({
                'id': msg.id,
                'mensagem': msg.mensagem,
                'direcao': msg.direcao,
                'tipo': msg.tipo,
                'data_envio': msg.data_envio.isoformat(),
                'usuario': msg.usuario.get_full_name() if msg.usuario else 'Sistema',
                'origem': msg.origem
            })
        
        return JsonResponse({
            'novas_mensagens': mensagens_data,
            'ultimo_id': novas_mensagens.last().id if novas_mensagens.exists() else last_message_id
        })
    
    # Código normal para requisições não-AJAX
    mensagens = HistoricoMensagem.objects.filter(
        phone_number=phone_number
    ).select_related('usuario').order_by("data_envio")
    
    # Obter informações do cliente para o contexto
    cliente_info = HistoricoMensagem.objects.filter(
        phone_number=phone_number
    ).values('nome_cliente', 'cliente').first()
    
    nome_cliente = cliente_info['nome_cliente'] if cliente_info and cliente_info['nome_cliente'] else "Cliente WhatsApp"
    cliente_id = cliente_info['cliente'] if cliente_info else None
    
    # Buscar conversas recentes para a sidebar
    conversas_recentes = HistoricoMensagem.objects.exclude(
        nome_cliente__isnull=True
    ).exclude(
        nome_cliente=''
    ).values(
        "phone_number", "nome_cliente"
    ).annotate(
        last_message_time=Max('data_envio')
    ).distinct().order_by("-last_message_time")[:10]
    
    if request.method == "POST":
        texto = request.POST.get("mensagem")
        atendente = request.user.get_full_name() or request.user.username
        
        if texto:
            try:
                # Formatar mensagem para WhatsApp
                texto_formatado = f"{atendente}: \n{texto}"
                
                # Enviar via WhatsApp
                return send_text_message(phone_number, texto_formatado, False)
                
                # Salvar no histórico
                nova_mensagem = HistoricoMensagem.objects.create(
                    phone_number=phone_number,
                    nome_cliente=nome_cliente,
                    mensagem=texto_formatado,
                    direcao="enviada",
                    tipo="texto",
                    origem="atendimento_manual",
                    data_envio=timezone.now(),
                    empresa=request.user.empresa if hasattr(request.user, 'empresa') else None,
                    cliente_id=cliente_id,
                    usuario=request.user
                )
                
                # Se for requisição AJAX, retornar JSON
                if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                    return JsonResponse({
                        'status': 'success',
                        'mensagem_id': nova_mensagem.id,
                        'mensagem': texto_formatado
                    })
                else:
                    messages.success(request, "Mensagem enviada com sucesso!")
                    return redirect("chat_cliente", phone_number=phone_number)
                
            except Exception as e:
                if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                    return JsonResponse({
                        'status': 'error',
                        'erro': str(e)
                    }, status=400)
                else:
                    messages.error(request, f"Erro ao enviar mensagem: {str(e)}")
    
    # Estatísticas da conversa
    estatisticas = {
        'total_mensagens': mensagens.count(),
        'mensagens_enviadas': mensagens.filter(direcao='enviada').count(),
        'mensagens_recebidas': mensagens.filter(direcao='recebida').count(),
        'primeira_mensagem': mensagens.first().data_envio if mensagens.exists() else timezone.now(),
        'ultimo_id': mensagens.last().id if mensagens.exists() else 0
    }
    
    return render(request, "whatsapp/chat_cliente.html", {
        "mensagens": mensagens, 
        "phone_number": phone_number,
        "nome_cliente": nome_cliente,
        "estatisticas": estatisticas,
        "cliente_id": cliente_id,
        "conversas_recentes": conversas_recentes
    })
    
    
    
    
