import re

def normalizar_telefone(telefone):
    if not telefone:
        return None

    # Remove tudo que não for número
    telefone = re.sub(r'\D', '', telefone)

    # Remove código do país 55 se existir
    if telefone.startswith("55"):
        telefone = telefone[2:]
        
    if len(telefone) == 8:  # Ex: XXXXXXXX
        telefone = "9" + telefone  # Adiciona o 9

    # Se não tiver DDD, adiciona 83
    if len(telefone) == 9:  # Ex: 9XXXXXXXX
        telefone = "83" + telefone
    
    # Adicionar o 9 se faltar em números antigos
    if len(telefone) == 10:  # Ex: XX9XXXXXXXX
        telefone = telefone[:2] + "9" + telefone[2:]
    
    return telefone

