def enviarUpdatesWithClientData(phone_number, message_body, orcamentoId, incluir_recibo=False, somente_recibo=False):
    """
    Sempre que o status do orçamento mudar:
    - Gera o PDF atualizado
    - Converte para Base64
    - Envia para o n8n
    - Apaga o arquivo local
    Com incluir_recibo=True, o recibo do valor pago vai embutido no mesmo PDF.
    Com somente_recibo=True, o PDF enviado é só o recibo (ex.: ao registrar um pagamento).
    """
    webhookN8nHttp = "http://127.0.0.1:5678/webhook/406cf98d-ed17-4b1e-a942-3e8b81edb584"
    pdf_path = png_path = None

    try:
        # Busca o orçamento
        orcamento = Orcamento.objects.get(id=orcamentoId, empresa_id=1)

        # Gera o PDF
        if somente_recibo:
            pdf_path = gerar_recibo(orcamento, orcamento.empresa)
            nome_arquivo = f"Recibo_{orcamento.cliente.nome}.pdf"
        else:
            pdf_path, png_path = gerar_arquivos(orcamento, orcamento.empresa, incluir_recibo=incluir_recibo)
            nome_arquivo = f"Orcamento_{orcamento.cliente.nome}.pdf"

        # Lê o PDF e converte para Base64
        with open(pdf_path, "rb") as f:
            pdf_bytes = f.read()

        pdf_base64 = base64.b64encode(pdf_bytes).decode("utf-8")
        phone_number = normalizar_telefone(phone_number)
        payload = {
            "phone_number": phone_number,
            "message_body": message_body,
            "document": {
                "filename": nome_arquivo,
                "mime": "application/pdf",
                "base64": pdf_base64
            }
        }

        response = requests.post(webhookN8nHttp, json=payload, timeout=30)

        if response.status_code != 200:
            print(
                f"❌ Erro ao enviar atualização via n8n "
                f"({response.status_code}): {response.text}"
            )
        else:
            print(f"✅ Atualização enviada via n8n para {phone_number}")

    except Orcamento.DoesNotExist:
        print(f"❌ Orçamento {orcamentoId} não encontrado")

    except Exception as e:
        print(f"❌ Erro ao enviar atualização via n8n: {str(e)}")

    finally:
        # Remove o arquivo PDF temporário
        try:
            for caminho in (pdf_path, png_path):
                if caminho and os.path.exists(caminho):
                    os.remove(caminho)
        except Exception as e:
            print(f"⚠️ Erro ao remover PDF temporário: {str(e)}")
            

