import threading
from django.contrib.auth.decorators import login_required
from django.db import close_old_connections
from django.views.decorators.http import require_POST

# Intervalo entre um envio e outro, para não disparar tudo de uma vez no WhatsApp
INTERVALO_ENVIO_EVENTOS = 40  # segundos

# Impede que dois cliques no botão disparem dois loops ao mesmo tempo
_envio_eventos_lock = threading.Lock()

# Sinal para o botão "Cancelar envios" interromper o loop durante a espera
_cancelar_envio_eventos = threading.Event()

# Progresso do envio em andamento, mostrado na tela de agendamentos
_progresso_envio_eventos = {"enviados": 0, "total": 0}


def enviar_em_segundo_plano(phone_number, message_body, orcamento_id, **kwargs):
    """
    Chama enviarUpdatesWithClientData numa thread, para a tela não ficar
    travada esperando o PDF ser gerado e o n8n responder.
    """
    def _enviar():
        close_old_connections()
        try:
            enviarUpdatesWithClientData(phone_number, message_body, orcamento_id, **kwargs)
        finally:
            close_old_connections()

    threading.Thread(target=_enviar, daemon=True).start()


