def status_envio_eventos():
    """Progresso do envio em andamento, ou None se não houver envio rodando."""
    if not _envio_eventos_lock.locked():
        return None
    return dict(_progresso_envio_eventos, cancelando=_cancelar_envio_eventos.is_set())


def eventos_em_aberto(empresa):
    """Eventos confirmados/reagendados que ainda vão acontecer (de hoje em diante)."""
    return (
        Orcamento.objects
        .filter(empresa=empresa, status__in=["confirmado", "reagendar"],
                data_evento__gte=timezone.localdate())
        .select_related("cliente")
        .order_by("data_evento", "hora_evento")
    )


def mensagem_preparando_evento(orcamento):
    data = orcamento.data_evento.strftime("%d/%m/%Y")
    hora = orcamento.hora_evento.strftime("%H:%M") if hasattr(orcamento.hora_evento, "strftime") else str(orcamento.hora_evento)
    return (
        f"Olá, {orcamento.cliente.nome}! 😊\n\n"
        f"Passando para avisar que já estamos preparando tudo para o seu evento do dia *{data}* às *{hora}*! 🎉🎪\n\n"
        "Nossa equipe está cuidando de cada detalhe para fazer desse o melhor evento! 💙✨\n\n"
        f"Segue o seu orçamento *#{orcamento.id}* para conferência. "
        "Se precisar ajustar algo, é só chamar a gente por aqui! 😊\n\n"
        f"{mensagem_recibo(orcamento)}"
        "— Mundo Kids 💙"
    )


def mensagem_recibo(orcamento):
    """Trecho extra para quem já pagou algo: avisa do recibo no PDF e da nota fiscal."""
    if not orcamento.valor_pago or orcamento.valor_pago <= 0:
        return ""
    return (
        f"🧾 No mesmo PDF também está o *recibo* do valor já pago ({formatar_reais(orcamento.valor_pago)}).\n\n"
        f"{AVISO_NOTA_FISCAL}"
    )


def _loop_envio_eventos(envios):
    """
    Roda em segundo plano: envia um orçamento + mensagem por vez via n8n,
    esperando INTERVALO_ENVIO_EVENTOS segundos entre um envio e o próximo.
    A espera é interrompida na hora se o envio for cancelado.
    """
    try:
        for indice, (telefone, mensagem, orcamento_id) in enumerate(envios):
            if indice > 0 and _cancelar_envio_eventos.wait(INTERVALO_ENVIO_EVENTOS):
                break
            if _cancelar_envio_eventos.is_set():
                break
            close_old_connections()
            print(f"📤 [{indice + 1}/{len(envios)}] Enviando atualização do orçamento #{orcamento_id}")
            enviarUpdatesWithClientData(telefone, mensagem, orcamento_id, incluir_recibo=True)
            _progresso_envio_eventos["enviados"] = indice + 1

        enviados = _progresso_envio_eventos["enviados"]
        if _cancelar_envio_eventos.is_set():
            print(f"🛑 Envio de atualização cancelado ({enviados} de {len(envios)} enviados)")
        else:
            print(f"🏁 Envio de atualização dos eventos em aberto finalizado ({enviados} envios)")
    finally:
        close_old_connections()
        _envio_eventos_lock.release()


@login_required
@require_POST
def enviar_atualizacao_eventos(request):
    """
    Botão da tela de agendamentos: dispara, em segundo plano, o envio do
    orçamento + mensagem "já estamos preparando tudo" para cada evento em
    aberto, um a cada INTERVALO_ENVIO_EVENTOS segundos.
    """
    if not _envio_eventos_lock.acquire(blocking=False):
        messages.warning(request, "Já existe um envio de atualizações em andamento. Aguarde terminar.")
        return redirect("orcamentos:agendamentos")

    try:
        envios = [
            (o.cliente.telefone, mensagem_preparando_evento(o), o.id)
            for o in eventos_em_aberto(request.user.empresa)
            if normalizar_telefone(o.cliente.telefone)
        ]
    except Exception:
        _envio_eventos_lock.release()
        raise

    if not envios:
        _envio_eventos_lock.release()
        messages.info(request, "Nenhum evento em aberto para enviar atualização.")
        return redirect("orcamentos:agendamentos")

    _cancelar_envio_eventos.clear()
    _progresso_envio_eventos.update(enviados=0, total=len(envios))
    threading.Thread(target=_loop_envio_eventos, args=(envios,), daemon=True).start()

    minutos = (len(envios) - 1) * INTERVALO_ENVIO_EVENTOS // 60
    messages.success(
        request,
        f"Envio iniciado para {len(envios)} evento(s) em aberto, um a cada "
        f"{INTERVALO_ENVIO_EVENTOS}s (cerca de {minutos} min no total)."
    )
    return redirect("orcamentos:agendamentos")


@login_required
@require_POST
def cancelar_envio_eventos(request):
    """Botão "Cancelar envios": interrompe o loop; nenhum envio novo sai depois disso."""
    status = status_envio_eventos()
    if status is None:
        messages.info(request, "Não há nenhum envio de atualizações em andamento.")
    else:
        _cancelar_envio_eventos.set()
        messages.warning(
            request,
            f"Envio cancelado. {status['enviados']} de {status['total']} mensagem(ns) já tinham sido enviadas."
        )
    return redirect("orcamentos:agendamentos")
